using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Checkout;

// Scenario: Gold customer receives the approved discount
//   Given a Gold customer has an order subtotal of 100.00
//   When checkout calculates the payable total
//   Then the payable total is 95.00
public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void GoldCustomerWithHundredSubtotalPaysNinetyFive()
    {
        var checkout = new CheckoutService();

        var payableTotal = checkout.CalculatePayableTotal(CustomerTier.Gold, subtotal: 100.00m);

        Assert.Equal(95.00m, payableTotal);
    }
}

